begin;
insert into public.faq_items (tenant_id,question_tr,answer_tr,category,sort_order,active)
select t.id,x.question,x.answer,'Üretim süreci',x.sort_order,true
from jsonb_to_recordset('[{"brand":"3dyanimda","question":"3D dosyam olmadan proje başlatabilir miyim?","answer":"Evet. Fikrinizi eskiz, fotoğraf, ölçü veya fiziksel numuneyle anlatabilirsiniz. Baskıya geçmeden önce hangi modelleme çalışmalarına ihtiyaç olduğunu birlikte belirleriz.","sort_order":10},{"brand":"3dyanimda","question":"Kişisel bir hobi projesi için de başvurabilir miyim?","answer":"Tek parça, kişisel aksesuar, masaüstü düzenleyici veya hobi prototipi taleplerinizi paylaşabilirsiniz. Üretilebilirlik, malzeme ve kapsam proje özelinde değerlendirilir.","sort_order":20},{"brand":"3dyanimda","question":"Teklif ekranında hangi dosyaları inceleyebilirim?","answer":"STL, OBJ, 3MF, STEP/STP ve IGES/IGS dosyaları desteklenir. Dosya başına sınır 20 MB’tır. Modelin boyutlarını ve yönünü kontrol ederek üretim tercihlerinizi belirtebilirsiniz.","sort_order":30},{"brand":"3dyanimda","question":"Ekrandaki anlık fiyat kesin satış fiyatı mı?","answer":"Anlık hesap, tanımlanmış malzeme ve fiyatlandırma ayarlarına dayanan bir ön tahmindir. Modelin üretilebilirliği, ek işlemler ve teslimat kapsamı değerlendirilerek nihai teklif netleştirilir.","sort_order":40},{"brand":"3dyanimda","question":"İlk prototipten sonra tasarımı değiştirebilir miyim?","answer":"İlk numuneyi form, montaj veya kullanım açısından değerlendirebilirsiniz. İstenen değişiklikleri yeni bir revizyon olarak tanımlayıp modelleme ve yeniden üretim kapsamını ayrıca planlarız.","sort_order":50},{"brand":"3dyanimda","question":"Hangi malzemeyi seçmeliyim?","answer":"Parçanın nerede kullanılacağını, taşıyacağı yükü, sıcaklık ve esneklik beklentinizi paylaşın. Sadece görünüş için hazırlanan bir model ile çalışan bir parçanın malzeme ihtiyacı farklı olabilir.","sort_order":60},{"brand":"3dyanimda","question":"Teslimat süresi ne zaman netleşir?","answer":"Dosya, adet, malzeme, yüzey işlemleri ve mevcut üretim planı incelendikten sonra süre bildirilir. Numune veya revizyon gerekiyorsa bu adımlar da teslimat planına eklenir.","sort_order":70},{"brand":"3dyanimda","question":"Dosyam üretime hazır değilse ne olur?","answer":"Eksik yüzey, ölçek veya ince detay gibi konuları değerlendirme aşamasında paylaşırız. Gereken düzenlemeler ve kapsam onaylanmadan tasarımın üretime uygun olduğu varsayılmaz.","sort_order":80},{"brand":"3dsanayi","question":"Bir aparat veya fikstür talebinde hangi bilgiler gerekli?","answer":"Parçanın görevini, eşleştiği yüzeyleri, kritik ölçüleri, adet ve kullanım koşullarını paylaşın. Teknik resim, CAD modeli ve çalışma istasyonu fotoğrafları kapsamı netleştirmeyi kolaylaştırır.","sort_order":10},{"brand":"3dsanayi","question":"CAD çizimi olmayan bir parçayı yeniden üretebilir miyiz?","answer":"Fiziksel numune, ölçüler ve montaj bilgileri üzerinden tarama veya modelleme ihtiyacını değerlendirebiliriz. Aşınmış ya da kırık bölgelerin özgün geometrisi ayrıca doğrulanmalıdır.","sort_order":20},{"brand":"3dsanayi","question":"Seri üretim öncesinde numune alınabilir mi?","answer":"Projenin gerektirdiği durumlarda ilk numune üzerinden montaj ve kullanım değerlendirmesi planlanabilir. Kabul kriterleri ve sonraki adetlerin kapsamı teklif aşamasında belirlenir.","sort_order":30},{"brand":"3dsanayi","question":"Üretim hattında kullanılacak malzemeye nasıl karar verilir?","answer":"Sıcaklık, yük, aşınma, kimyasal temas ve çalışma çevrimi birlikte değerlendirilir. Malzeme seçimi yalnızca genel dayanım ifadelerine değil, uygulamanızın koşullarına dayanmalıdır.","sort_order":40},{"brand":"3dsanayi","question":"Hangi teknik dosyaları gönderebilirim?","answer":"Teklif ekranı STL, OBJ, 3MF, STEP/STP ve IGES/IGS modellerini kabul eder; dosya başına sınır 20 MB’tır. Kritik toleransları ayrıca talep açıklamasında belirtin.","sort_order":50},{"brand":"3dsanayi","question":"Tolerans ve kalite beklentisini nasıl paylaşmalıyım?","answer":"Montaj referanslarını, kabul ölçülerini ve kontrol yöntemini teknik resimde veya açıklamada tanımlayın. Belirli bir tolerans ya da sertifika, proje için doğrulanmadan taahhüt edilmiş sayılmaz.","sort_order":60},{"brand":"3dsanayi","question":"Teklifte adet artışı nasıl ele alınır?","answer":"İstenen adetle birlikte tekrar sipariş beklentinizi de yazabilirsiniz. Üretim, hazırlık ve ek işlem maliyetleri değerlendirilerek partiye uygun teklif hazırlanır.","sort_order":70},{"brand":"3dsanayi","question":"Bakım için acil parça ihtiyacını iletebilir miyim?","answer":"İstenen tarihi ve duruşun nedenini talebinizde belirtin. Üretilebilirlik ve kapasite kontrolünden sonra uygulanabilir plan paylaşılır; inceleme yapılmadan teslimat garantisi verilmez.","sort_order":80},{"brand":"maketyanimda","question":"Maket teklifi için nereden başlamalıyım?","answer":"Projenin sunum amacını, istediğiniz ölçeği, yaklaşık taban ölçüsünü ve teslim tarihini paylaşın. Kütle, cephe, peyzaj ve aydınlatma gibi detayları kapsamın parçası olarak ayrıca belirtin.","sort_order":10},{"brand":"maketyanimda","question":"Ölçek seçimi maketin detaylarını nasıl etkiler?","answer":"Küçük ölçekte bazı ince detayların sadeleştirilmesi gerekebilir. Sunum mesafesi, taban alanı ve vurgulanacak bölümler birlikte değerlendirilerek okunaklı bir maket kurgusu hazırlanır.","sort_order":20},{"brand":"maketyanimda","question":"Mimari modelim doğrudan baskıya uygun mu?","answer":"Görselleştirme için hazırlanmış modeller her zaman üretime uygun olmayabilir. Duvar kalınlıkları, birleşimler, boşluklar ve küçük elemanlar maket ölçeğinde ayrıca kontrol edilir.","sort_order":30},{"brand":"maketyanimda","question":"Teklif ekranına hangi model dosyalarını ekleyebilirim?","answer":"STL, OBJ, 3MF, STEP/STP ve IGES/IGS dosyaları desteklenir. Dosya başına sınır 20 MB’tır. Farklı bir mimari dosya biçiminiz varsa hangi formatta paylaşabileceğinizi iletişimden sorabilirsiniz.","sort_order":40},{"brand":"maketyanimda","question":"Renk, peyzaj ve yüzey bitişi talep edebilir miyim?","answer":"Beklediğiniz sunum dilini referans görsellerle anlatabilirsiniz. Renk, taban, çevre elemanları ve son işlemler temel baskıdan ayrı değerlendirilebilen proje kalemleridir.","sort_order":50},{"brand":"maketyanimda","question":"Maket taşınabilir veya modüler hazırlanabilir mi?","answer":"Taşıma, kurulum ve saklama koşullarınızı başlangıçta paylaşın. Taban ölçüsü ve proje geometrisine göre bölünebilir parçalar ile bağlantı detayları değerlendirilir.","sort_order":60},{"brand":"maketyanimda","question":"Maket fiyatını hangi bilgiler belirler?","answer":"Ölçek, toplam ölçüler, detay seviyesi, model hazırlığı, malzemeler ve son işlemler birlikte değerlendirilir. Yalnızca bina sayısı veya baskı hacmi nihai maliyeti açıklamak için yeterli olmayabilir.","sort_order":70},{"brand":"maketyanimda","question":"Sunum öncesi revizyon yapabilir miyim?","answer":"Güncel proje dosyasını ve değişen alanları belirtin. Revizyonun model hazırlığına, üretilmiş parçalara ve teslimat planına etkisi ayrıca değerlendirilir.","sort_order":80},{"brand":"parcayanimda","question":"Kırık veya kayıp bir plastik parça için ne göndermeliyim?","answer":"Parçanın fotoğrafını, yaklaşık ölçülerini ve monte edildiği yeri paylaşın. Varsa sağlam numune veya eş parça, bağlantı geometrisini anlamamıza yardımcı olur.","sort_order":10},{"brand":"parcayanimda","question":"Tek adet parça yaptırabilir miyim?","answer":"Tek adet taleplerinizi iletebilirsiniz. Model hazırlığı, malzeme ve üretim gereksinimleri değerlendirilerek parçaya özel kapsam ve fiyat belirlenir.","sort_order":20},{"brand":"parcayanimda","question":"Parçanın yerine oturacağını nasıl kontrol ederiz?","answer":"Eşleşen yüzeyleri, delik mesafelerini ve kritik ölçüleri belirtin. Gerekli durumlarda ilk numune üzerinden uyum değerlendirmesi ve revizyon planlanabilir.","sort_order":30},{"brand":"parcayanimda","question":"Dış ortamda kullanılacak parça için hangi bilgiler gerekli?","answer":"Güneş, su, sıcaklık, yük ve kullanım sıklığı gibi koşulları paylaşın. Malzeme ve üretim yaklaşımı bu koşullara göre değerlendirilir; her plastik her ortam için uygun değildir.","sort_order":40},{"brand":"parcayanimda","question":"Güvenlik açısından kritik parçaları da üretiyor musunuz?","answer":"Yük taşıyan, araç güvenliğini etkileyen veya özel standart gerektiren uygulamalar ayrıca değerlendirilir. Dosyanın kabul edilmesi, parçanın ilgili kullanım için onaylandığı anlamına gelmez.","sort_order":50},{"brand":"parcayanimda","question":"Hazır modelimi hangi biçimde yükleyebilirim?","answer":"STL, OBJ, 3MF, STEP/STP ve IGES/IGS dosyalarını teklif ekranında inceleyebilirsiniz. Dosya başına sınır 20 MB’tır. Doğru birimi ve ölçüleri göndermeden önce kontrol edin.","sort_order":60},{"brand":"parcayanimda","question":"Orijinal parçanın rengini ve yüzeyini eşleştirebilir miyiz?","answer":"Renk ve görünüş beklentinizi fotoğraf veya numuneyle belirtin. Malzeme ve üretim yöntemine bağlı farklılıklar olabilir; birebir eşleşme değerlendirme yapılmadan taahhüt edilmez.","sort_order":70},{"brand":"parcayanimda","question":"Tekrar siparişte aynı modeli kullanabilir miyim?","answer":"Önceki teklif veya model bilgisini ve istediğiniz adedi paylaşın. Dosyanın doğru revizyonu ile güncel malzeme, kapsam ve fiyat koşulları doğrulanarak yeni sipariş değerlendirilir.","sort_order":80}]'::jsonb) as x(brand text,question text,answer text,sort_order int)
join public.tenants t on t.slug=x.brand
where not exists(select 1 from public.faq_items f where f.tenant_id=t.id and f.question_tr=x.question);
update public.tenant_features set enabled=true,updated_at=now()
where tenant_id in (select id from public.tenants where slug in ('3dyanimda','3dsanayi','maketyanimda','parcayanimda'))
and feature_key in ('career','career.machine_ops','portfolio','faq','admin.jobs','admin.portfolio','admin.faq','admin.applications','admin.machine_ops');
commit;
select t.slug,(select count(*) from faq_items f where f.tenant_id=t.id and f.active) as active_faq,(select jsonb_object_agg(feature_key,enabled) from tenant_features tf where tf.tenant_id=t.id and feature_key in ('career','career.machine_ops','portfolio','faq','admin.jobs','admin.portfolio','admin.faq','admin.applications','admin.machine_ops')) as modules from tenants t where slug in ('3dyanimda','3dsanayi','maketyanimda','parcayanimda');
